steps.analogousExample:
/* Example of styling a box */
.box {
  background-color: coral;
  height: 80px;
  width: 150px;
}

/* Example: adding top margin to an element */
.header {
  margin-top: 20px;
}

/* Similar: adding bottom margin to an element */
.example {
  margin-bottom: 25px;
}

/* Similar: adding margin to an element */
.element {
  margin-top: 20px;
}

/* Adding a border to an element */
.example {
  border: 2px solid red;
}

/* Example: adding padding to an element */
.element {
  padding: 15px;
}

/* Similar: nested divs with parent margin */
.parent {
  margin-top: 50px;
}
.child {
  background-color: lightblue;
}

/* Adding padding to prevent margin collapse */
.parent {
  padding-top: 1px;
}
